"""«Ася» — ИИ-запись клиентов падел-клуба «Сетка»: день, время и длительность из текста, свободные корты, бронь, перенос, отмена."""
from ..ai import FAQ_COMMON
from ._t import theme

JS = r"""
(function(){var K=AIK,MN=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'],
 MR=['январ','феврал','март','апрел','ма[йя]','июн','июл','август','сентябр','октябр','ноябр','декабр'],
 WN=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'],WR=[/воскресен/i,/понедельник/i,/вторник/i,/сред[ауы]/i,/четверг/i,/пятниц/i,/суббот/i];
function d0(){var d=new Date();d.setHours(0,0,0,0);return d}
function add(d,n){d=new Date(d);d.setDate(d.getDate()+n);return d}
function fd(d){return d.getDate()+' '+MN[d.getMonth()]+', '+WN[d.getDay()]}
function ft(m){return Math.floor(m/60)+':'+('0'+m%60).slice(-2)}
function rub(n){return K.fmt(n)+' ₽'}
function busy(d,c,m){var h=Math.floor(m/60),k=(d.getDate()*31+c*17+h*13+d.getMonth()*7)%7,we=d.getDay()%6===0;return k<((h>=18&&h<22)?5:(we&&h>=10)?3:1)}
function free(d,c,s,len){if(s<420||s+len>1380)return false;for(var m=s;m<s+len;m+=30)if(busy(d,c,m))return false;return true}
function cost(d,s,len){var we=d.getDay()%6===0,t=0;for(var m=s;m<s+len;m+=30)t+=(we||m>=1020)?1800:1200;return t}
var NW=[['одиннадцат\\S*',11],['двенадцат\\S*',12],['десят\\S*',10],['девят\\S*',9],['вос[ье]м\\S*',8],['сем[иь]',7],['шест[иь]',6],['пят[иь]',5],['четыр[её]х',4],['тр[её]х',3]];
function parse(t,S){var m,t0=d0(),i,got=0,tset=0;
 NW.forEach(function(x){t=t.replace(new RegExp('(^|\\s)(в|к|после|с|до|около)\\s+'+x[0]+'(?![а-яё])','gi'),'$1$2 '+x[1])});
 if(/послезавтра/i.test(t)){S._d=add(t0,2);got=1}else if(/завтра/i.test(t)){S._d=add(t0,1);got=1}else if(/сегодня/i.test(t)){S._d=t0;got=1}
 else if(m=t.match(/(\d{1,2})\s+([а-яё]{3,})/i)){for(i=0;i<12;i++)if(new RegExp('^'+MR[i]).test(m[2].toLowerCase())){S._d=new Date(t0.getFullYear(),i,+m[1]);if(S._d<t0)S._d.setFullYear(t0.getFullYear()+1);got=1}}
 if(!got)for(i=0;i<7;i++)if(WR[i].test(t)){S._d=add(t0,(i-t0.getDay()+7)%7||7);got=1}
 if(m=t.match(/с\s*(\d{1,2})(?:[:.](\d{2}))?\s*(?:до|по)\s*(\d{1,2})(?:[:.](\d{2}))?/i)){var a=+m[1]*60+(+m[2]||0),b=+m[3]*60+(+m[4]||0);if((a<420&&b<=720)||(/вечер/i.test(t)&&a<720)){a+=720;b+=720}if(b>a){tset=1;S._s=a;S._len=Math.min(180,Math.max(60,Math.round((b-a)/30)*30))}}
 else if(m=t.match(/(?:в|к|на|после|с|около)\s*(\d{1,2})(?:[:.](\d{2}))?\s*(час\S*\s+)?(вечера|дня|утра)?(?!\s*(?:минут|ракет|человек|игрок|[а-яё]*бр))/i)){var h=+m[1],mi=+m[2]||0;if(m[4]&&/вечера|дня/.test(m[4])&&h<12)h+=12;else if(!m[4]&&h>0&&h<7)h+=12;if(h>=7&&h<=22){tset=1;S._s=Math.round((h*60+mi)/30)*30}}
 else if(/утр/i.test(t)){tset=1;S._s=540}else if(/дн[её]м|в обед/i.test(t)){tset=1;S._s=780}else if(/вечер/i.test(t)){tset=1;S._s=1140}
 if(!tset&&S._b&&(m=t.match(/на\s+(пол)?час\S*\s+(позже|раньше)/i)))S._s=S._b.s+(m[1]?30:60)*(m[2]==='позже'?1:-1);
 if(/полтора|полутора|90\s*мин/i.test(t))S._len=90;else if(/два часа|2\s*часа|на два|120\s*мин/i.test(t))S._len=120;else if(/на час(?![а-яё])(?!\s+(?:позже|раньше))|(?:^|\s)1\s*час|60\s*мин|часик/i.test(t))S._len=60;
 if(/вчетвером|четверо|4\s*(?:человек|игрок)/i.test(t))S._p=4;else if(/втро[её]м|трое|3\s*(?:человек|игрок)/i.test(t))S._p=3;else if(/вдво[её]м|двое|2\s*(?:человек|игрок)/i.test(t))S._p=2;
 if(!S._d)S._d=add(t0,1);if(!S._s)S._s=1140;if(!S._len)S._len=90;if(!S._p)S._p=4;
 if(+S._d===+t0){var now=new Date(),nm=Math.ceil((now.getHours()*60+now.getMinutes()+30)/30)*30;if(S._s<nm)S._s=Math.min(nm,1290)}
 S['День']=fd(S._d);S['Время']=ft(S._s);S['Длительность']=S._len===60?'1 час':S._len===90?'1,5 часа':S._len/60+' часа';S['Игроков']=String(S._p)}
function options(S){var d=S._d,len=S._len,o=[],c,k;for(c=1;c<=4;c++)if(free(d,c,S._s,len))o.push({c:c,s:S._s});S._exact=o.length;
 if(!o.length)for(k=1;k<=6&&o.length<3;k++){[S._s-30*k,S._s+30*k].forEach(function(s){if(o.length>=3)return;for(var c=1;c<=4;c++)if(free(d,c,s,len)){o.push({c:c,s:s});break}})}
 S._opt=o.slice(0,3);return S._opt}
function grid(S,sel){var d=S._d,from=Math.max(420,Math.min(S._s,sel?sel.s:S._s)-60),cols=8,h='<div class="gr" style="--n:'+cols+'"><span></span>';
 for(var i=0;i<cols;i++)h+='<b>'+(i%2?'':ft(from+i*30))+'</b>';
 for(var c=1;c<=4;c++){h+='<span>Корт '+c+'</span>';for(i=0;i<cols;i++){var m=from+i*30,on=sel&&sel.c===c&&m>=sel.s&&m<sel.s+S._len;h+='<i class="'+(on?'on':busy(d,c,m)||m>=1380?'bz':'')+'"></i>'}}
 return{html:h+'</div><p class="grl"><i class="bz"></i>занято<i></i>свободно<i class="on"></i>ваша игра</p>'}}
function sum(S){var c=cost(S._d,S._b.s,S._len)+(S._rk||0)*400;S._total=rub(c);S._each=rub(Math.round(c/S._p/10)*10);return c}
function card(S){var b=S._b;sum(S);var rows=[['День',fd(S._d)],['Время',ft(b.s)+' – '+ft(b.s+S._len)],['Корт','№ '+b.c+(b.c<3?', панорамный':', классический')],['Игроков',String(S._p)]];
 if(S._rk)rows.push(['Ракетки напрокат',S._rk+' × 400 ₽']);rows.push(['С каждого',S._each]);return{t:'kv',h:'Бронь № С-3172',rows:rows,sum:['Итого',S._total]}}
K.hook=function(t,S,it){var m,ov=null;S['Запрос']=it.label||'вопрос';
 if(it.id==='find'||it.id==='move'||it.id==='reserve'||!S._d)parse(t,S);
 if(it.id==='move'&&!S._b)ov='find';
 if(it.id==='reserve'||it.id==='move'){var o=S._opt||options(S),pick=null,tm=t.match(/(\d{1,2})[:.](\d{2})/),cm=t.match(/корт\S*\s*№?\s*(\d)/i);
  if(it.id==='move'){options(S);o=S._opt}
  if(tm||cm)o.forEach(function(x){if((!tm||x.s===+tm[1]*60+ +tm[2])&&(!cm||x.c===+cm[1])&&!pick)pick=x});
  if(!pick&&cm&&free(S._d,+cm[1],tm?+tm[1]*60+ +tm[2]:S._s,S._len))pick={c:+cm[1],s:tm?+tm[1]*60+ +tm[2]:S._s};
  pick=pick||o[0];S._note=(pick&&cm&&pick.c!==+cm[1])?'Корт № '+cm[1]+' на это время занят, поэтому взяла корт № '+pick.c+'. ':'';if(pick){S._old=S._b;S._b=pick;S['Время']=ft(pick.s);S['Корт']='№ '+pick.c;S._later=ft(Math.min(pick.s+60,1380-S._len));sum(S)}else ov='none'}
 if(it.id==='rackets'){if(!S._b){ov='find'}else{m=t.match(/(\d)\s*ракет|(одн|две|три|четыре)\S*\s*ракет/i);S._rk=m?(m[1]?+m[1]:/одн/.test(m[2])?1:/две/.test(m[2])?2:/три/.test(m[2])?3:4):S._p;sum(S)}}
 if(it.id==='cancel'){if(!S._b)ov='nobook';else{var st=new Date(S._d);st.setMinutes(S._b.s);var hrs=(st-new Date())/36e5;S._fee=hrs>=24?'без удержаний':'с удержанием 50%: до игры меньше суток';S._was=fd(S._d)+', '+ft(S._b.s)+', корт № '+S._b.c}}
 if(ov==='find')parse(t,S);return ov};
K.parts.fields=function(S){return['Запрос','День','Время','Длительность','Игроков','Корт'].filter(function(k){return S[k]}).map(function(k){return[k,S[k]]})};
K.parts.find=function(S){delete S['Корт'];var o=options(S),out=[];
 if(!o.length)return['На '+fd(S._d)+' рядом с '+ft(S._s)+' свободных кортов на '+S['Длительность']+' нет. Назовите другое время или день — посмотрю ещё.'];
 out.push(S._exact?'На '+fd(S._d)+' в '+ft(S._s)+' свободно, '+S['Длительность']+':':'Ровно в '+ft(S._s)+' все корты заняты. Ближайшие свободные окна на '+S['Длительность']+':');
 out.push(grid(S,o[0]));
 out.push({t:'items',items:o.map(function(x,i){var c=cost(S._d,x.s,S._len);return{tag:i?'':'Ближе всего к вашему времени',n:ft(x.s)+' – '+ft(x.s+S._len)+', корт № '+x.c,s:(x.c<3?'панорамный':'классический')+' · '+rub(Math.round(c/S._p/10)*10)+' с каждого из '+S._p,p:rub(c),b:['Забронировать','reserve','Бронирую '+ft(x.s)+', корт '+x.c]}})});
 return out};
K.parts.reserve=function(S){return[(S._note||'')+'Корт за вами:',grid(S,S._b),card(S),'Напомню за сутки и за 2 часа до игры. Ракетки и мячи можно взять напрокат, сказать администратору?']};
K.parts.move=function(S){return['Перенесла игру'+(S._old?' с '+ft(S._old.s)+' на '+ft(S._b.s):'')+'. Старое время освободила.',grid(S,S._b),card(S)]};
K.parts.rk=function(S){return['Добавила '+S._rk+' '+(S._rk===1?'ракетку':S._rk<5?'ракетки':'ракеток')+' напрокат, мячи выдадим бесплатно. Администратор подготовит всё к началу игры.',card(S)]};
K.parts.cancel=function(S){var out=['Отменила бронь: '+S._was+'. Отмена '+S._fee+'.'+(/без/.test(S._fee)?' Предоплату вернём на карту в течение 3 дней.':'')];S._b=null;S._rk=0;delete S['Корт'];return out};
})();
"""

